public class Main {
    public static void main(String[] args) {
        Point a = new Point(1, 2);
        Point b = new Point(4, 6);
        System.out.println(a);
        System.out.println(b);
    }
}

class Point {
    private final int x;
    private final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return x + "," + y;
    }
}
